'use strict';
const details=[
{title:'An open door.',word:'Welcome',body:'A magnificent hotel can offer a room. A home offers belonging. The spare chair turns a landscape into an invitation: you are wanted here.',question:'Who helps you feel that you belong, without needing to impress anyone?',practice:'Welcome someone who might otherwise be left at the edge.'},
{title:'A table, not a ticket.',word:'Communion',body:'A ticket gives access to a place. A shared table hints at something deeper: life together. Heaven is not a private prize, but the fullness of communion with God and, in him, with others.',question:'What makes a meal with people you love different from the same food eaten alone?',practice:'Share a little time with someone, without rushing to the next thing.'},
{title:'Known. And loved.',word:'Presence',body:'Being near somebody is not the same as being truly present. In this small scene, one person gives another their whole attention. It is a tiny, imperfect hint of being fully known and loved by God.',question:'When did someone last listen to you so well that the rest of the room seemed to disappear?',practice:'Listen to someone without preparing your answer.'},
{title:'Not merely near God.',word:'Unity',body:'Jon’s shift was from “God is there too” to “entering God.” The Catechism speaks of entering the perfect unity of the Blessed Trinity: sharing in God’s life by grace, not becoming God or losing who we are.',question:'What changes when the heart of the picture is a relationship, rather than a location?',practice:'Pause and pray: Father, Son, and Holy Spirit, make your home in me.'},
{title:'The door is already ajar.',word:'Already',body:'The final line of Jon’s quotation brings eternity into today: even now, we are called to be a dwelling for the Trinity. A cup of water is not heaven itself. But love can open an ordinary moment toward God.',question:'Where could you make a little more room for love today?',practice:'Offer one small act of care, freely and without keeping count.'}
];
const seen=new Set();let current=-1;
const pins=[...document.querySelectorAll('.pin')], bars=[...document.querySelectorAll('.progress span')];
const next=document.querySelector('#next'), keepsake=document.querySelector('#keepsake');
function openDetail(i){
current=i;seen.add(i);pins.forEach((p,n)=>{p.setAttribute('aria-pressed',String(n===i));p.classList.toggle('seen',seen.has(n));bars[n].classList.toggle('done',seen.has(n))});
const d=details[i],w=document.querySelector('#words');w.replaceChildren();
const h=document.createElement('h2');h.textContent=d.title;
const p=document.createElement('p');p.textContent=d.body;
const q=document.createElement('p');q.className='question';q.textContent=d.question;w.append(h,p,q);
w.classList.remove('reveal');void w.offsetWidth;w.classList.add('reveal');
document.querySelector('#chapter').textContent=String(i+1).padStart(2,'0')+' / '+d.word;
document.querySelector('#count').textContent=seen.size+' / 5 opened';
next.textContent=seen.size===5?'Carry a little home ↓':'Open another detail →';
document.querySelector('#scene').classList.toggle('complete',seen.size===5);
if(seen.size===5){keepsake.hidden=false;document.querySelector('#summary').textContent='Five glimpses: welcome, communion, presence, unity, already. One way to begin: '+d.practice;}
}
pins.forEach((p,i)=>p.addEventListener('click',()=>openDetail(i)));
next.addEventListener('click',()=>{if(seen.size===5){keepsake.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});document.querySelector('#intention').focus({preventScroll:true});}else openDetail(details.findIndex((_,i)=>!seen.has(i)))});
document.querySelector('#save').addEventListener('click',()=>{
const intention=document.querySelector('#intention').value.trim()||details[Math.max(0,current)].practice;
const text='BEYOND THE POSTCARD\n\nHeaven is not merely beautiful scenery, but communion with God.\n\nToday, I can make room for love by…\n'+intention+'\n\nInspired by Jon’s “On Heaven” (2013).\nCatechism of the Catholic Church, paragraph 260.\n';
const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='beyond-the-postcard.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#notice').textContent='Your text keepsake is ready to save.';
});
document.querySelector('#print').addEventListener('click',()=>window.print());
document.querySelector('#restart').addEventListener('click',()=>{seen.clear();keepsake.hidden=true;document.querySelector('#notice').textContent='';openDetail(0);document.querySelector('#scene').scrollIntoView({block:'center'});pins[0].focus({preventScroll:true})});
</script></body></html>
